const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = total_wealth

const btc_usd_rate = require('btc_usd_rate')

async function total_wealth(opts = {}, protocol) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    data: ondata,
    icons: iconject,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  let dricons = []

  shadow.innerHTML = `
    <div class="total-wealth-container">
      <div class="total-wealth-header">Total wealth</div>
      <div class="total-wealth-value">
        <span>₿ 0.0000</span>
        <div class="total-wealth-usd">= $0</div>
      </div>
      <div class="wallet-row">
        <div class="lightning-icon"></div>
        Lightning Wallet <span>0.0000</span>
      </div>
      <div class="wallet-row">
        <div class="btc-icon"></div>
        Bitcoin Wallet <span>0.0000</span>
      </div>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')

  await sdb.watch(onbatch)

  const { io } = net(id)
  io.on.home_contents = function (m) {
    if (m.type === 'update') renderValues(m.data).catch(e => console.warn('[total_wealth] renderValues error:', e))
  }
  el.invite = io.invite('home_contents', { total_wealth: id })

  return el

  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw)))
      const func = on[type] || fail
      func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]

  }

  function ondata(data) {
    renderValues(data[0]?.value || {}).catch(e => console.warn('[total_wealth] renderValues error:', e))
  }


  async function renderValues({ total = 0, lightning = 0, bitcoin = 0 }) {
    shadow.querySelector('.total-wealth-value span').textContent = `₿ ${total}`
    shadow.querySelectorAll('.wallet-row')[0].querySelector('span').textContent = Number.isFinite(Number(lightning))
      ? Number(lightning).toFixed(7)
      : '0.0000000'
    shadow.querySelectorAll('.wallet-row')[1].querySelector('span').textContent = bitcoin

    if (dricons.length) {
      shadow.querySelector('.btc-icon').innerHTML = dricons[0]  // btc.svg
      shadow.querySelector('.lightning-icon').innerHTML = dricons[1] // lightning.svg
    }

    try {
      const rate = await btc_usd_rate('btc', 'usd')
      const usd = rate ? rate * total : null
      shadow.querySelector('.total-wealth-usd').textContent = usd !== null
        ? `= $${usd.toLocaleString(undefined, { maximumFractionDigits: 2 })}`
        : ''
    } catch (err) {
      console.warn('[total_wealth] usd rate update failed:', err)
      shadow.querySelector('.total-wealth-usd').textContent = ''
    }
  }

  function iconject(data) {
    dricons = data
  }
}

// ============ Fallback Setup for STATE ============

function fallback_module() {
  return {
    api: fallback_instance,
    _: { 'net_helper': { $: '' }, 'btc_usd_rate': { $: '' } }
  }

  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    return {
      drive: {
        'icons/': {
          'btc.svg': {
            '$ref': 'btc.svg'
          },
          'lightning.svg': {
            '$ref': 'lightning.svg'
          }
        },
        'style/': {
          'total_wealth.css': {
            '$ref': 'total_wealth.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      }
    }
  }
}
